fib_cache = {}
fib_sum_cache = {}

def fib(n):
    """Calculate fibonacci f_n where f_0=1, f_1=1, f_2=2, etc."""
    if n in fib_cache:
        return fib_cache[n]
    if n == 0 or n == 1:
        fib_cache[n] = 1
        return 1

    fib_cache[n] = fib(n-1) + fib(n-2)
    return fib_cache[n]

def fib_sum(n):
    """Calculate sum(f_1 + f_2 + ... + f_n) where our indexing starts at 1"""
    if n == 0:
        return 0
    if n not in fib_sum_cache:
        fib_sum_cache[n] = fib_sum(n-1) + fib(n-1)
    return fib_sum_cache[n]

class Solution:
    def __init__(self, n):
        self.n = n
        # Precompute prefix sums of fibonacci values
        self.fib_prefix = [0] * (n + 2)
        for i in range(1, n + 2):
            self.fib_prefix[i] = self.fib_prefix[i-1] + fib(i-1)

    def get_fib_sum_range(self, l, r):
        """Get sum of fibonacci values f_l to f_r"""
        # Since f_0 = 1, f_1 = 1 (array index 1 corresponds to f_1)
        return self.fib_prefix[r+1] - self.fib_prefix[l]

class SegmentTree:
    def __init__(self, n, fib_prefix):
        self.n = n
        self.fib_prefix = fib_prefix
        self.tree_sum = [0] * (4 * n + 1)  # Stores actual weighted sum
        self.tree_add = [0] * (4 * n + 1)  # Lazy propagation for range adds
        self.tree_base = [0] * (4 * n + 1) # Base contribution to maintain weights

    def push_up(self, node):
        """Update current node from children"""
        self.tree_sum[node] = self.tree_sum[2*node] + self.tree_sum[2*node+1]

    def push_down(self, node, left, right):
        """Propagate lazy updates"""
        if self.tree_add[node] != 0:
            mid = (left + right) // 2
            left_range = self.get_fib_sum_range(left, mid)
            right_range = self.get_fib_sum_range(mid+1, right)

            if left_range + right_range == 0:
                return

            self.tree_add[2*node] += self.tree_add[node]
            self.tree_sum[2*node] += self.tree_add[node] * left_range

            self.tree_add[2*node+1] += self.tree_add[node]
            self.tree_sum[2*node+1] += self.tree_add[node] * right_range

            self.tree_add[node] = 0

    def get_fib_sum_range(self, l, r):
        """Get sum of fibonacci values f_l to f_r"""
        return self.fib_prefix[r+1] - self.fib_prefix[l]

