def solve_primes(l, r):
    max_val = max(l, r)
    if max_val < 2:
        return 0

    limit = int(math.isqrt(max_val)) + 1
    sieve = [True] * limit
    sieve[0] = sieve[1] = False

    for i in range(2, int(math.isqrt(limit)) + 1):
        if sieve[i]:
            for j in range(i * i, limit, i):
                sieve[j] = False

    primes_to_check = [i for i in range(limit) if sieve[i]]

    def is_prime(n):
        if n < limit:
            return sieve[n]
        for p in primes_to_check:
            if p * p > n:
                break
            if n % p == 0:
                return False
        return True

    count = 0
    for n in range(l, r + 1):
        if is_prime(n) and (n == 2 or n % 4 == 1):
            count += 1
    return count

