def compute_domination(n, m):
    """Compute domination number for n x m grid"""
    # Handle specific cases with known formulas

    # For 1D grids (1×n or n×1)
    if n == 1 or m == 1:
        return math.ceil(n * m / 3)

    # For 2D grids with one dimension = 2 (2×n or n×2)
    if n == 2 or m == 2:
        return math.ceil(n * m / 3)

    # For n,m both >= 3, we need to search
