def get_equivalence_representative(s):
    """
    Find the lexicographically minimum string in the equivalence class.
    Equivalence class includes:
    - Original string
    - Reversed string
    - Complemented string (0->1, 1->0)
    - Complemented reversed string
    """
    n = len(s)

    # Generate all 4 variations
    variations = []

    # Original
    variations.append(s)

    # Reversed
    variations.append(s[::-1])

    # Complemented
    complementary = ''.join('1' if c == '0' else '0' for c in s)
    variations.append(complementary)

    # Complemented reversed
    variations.append(complementary[::-1])

    # Find minimum
    return min(variations)

def get_sorted_minimal_representatives(n):
    """Generate all unique minimal representatives sorted."""
    minimal_reps = set()

    # Generate all possible strings
    for i in range(2 ** n):
        s = bin(i)[2:].zfill(n)

        if s not in minimal_reps:
            # Find the minimum from its equivalence class
            rep = get_equivalence_representative(s)
            minimal_reps.add(rep)

    return sorted(minimal_reps)

