        maxx, maxy, w = map(int, parts)
    except:
        return "-1"

    # Precompute lucky tickets grouped by a value
    # lucky[a] contains list of b values that form lucky tickets with a
    lucky = {}

    for a in range(1, maxx + 1):
        ra = rev(a)
        for b in range(1, maxy + 1):
            rb = rev(b)
            if a * b == ra * rb:
                if a not in lucky:
                    lucky[a] = []
                lucky[a].append(b)

    best_x = -1
    best_y = -1
    best_cost = float('inf')

    # For each possible x from 1 to maxx
    for x in range(1, maxx + 1):
        # Collect all b values from series 1 to x
        all_b = []
        for a in range(1, x + 1):
            if a in lucky:
                all_b.extend(lucky[a])

        if len(all_b) < w:
            continue

        # Sort b values to find the minimum y that gives at least w lucky tickets
        all_b.sort()
        min_y = all_b[w - 1]

        # Check if this is better than current best
        if x * min_y < best_cost:
            best_cost = x * min_y
            best_x = x
            best_y = min_y

    if best_x != -1:
        return f"{best_x} {best_y}"
    return "-1"

