        return "-1\n"

    # Map each judge to a mask of which primes they can eliminate
    min_e_by_mask = {}

    for i in range(n):
        mask = 0
        for j in range(num_primes):
            if a[i] % primes[j] == 0:
                mask |= (1 << j)

        # Judge can eliminate these primes using appropriate divisor
        # Only keep mask if it's non-zero (they can eliminate something useful)
        if mask > 0:
            if mask not in min_e_by_mask:
                min_e_by_mask[mask] = e[i]
            else:
                min_e_by_mask[mask] = min(min_e_by_mask[mask], e[i])

    if not min_e_by_mask:
        return "-1\n"

    unique_masks = list(min_e_by_mask.keys())
    best_cost = float('inf')

    # For small number of unique masks, brute force all combinations
    # This works because 2^|primes| is small (at most ~15-20 for 10^12)
    num_unique = len(unique_masks)

    if num_unique <= 20:
        for r in range(1, num_unique + 1):
            for combo in itertools.combinations(unique_masks, r):
                covered = 0
                total_e = 0
                for mask in combo:
                    covered |= mask
                    total_e += min_e_by_mask[mask]

                if covered == full_mask:
                    cost = r * total_e
                    if cost < best_cost:
                        best_cost = cost

    if best_cost == float('inf'):
        return "-1\n"

    return f"{best_cost}\n"

