class SolutionFinder:
    def __init__(self, r, v):
        self.r = float(r)
        self.v = float(v)

    def solve_alpha(self, delta):
        """Find alpha such that r * (alpha - 2*sin(alpha/2)) = delta using binary search"""
        def f(alpha):
            return alpha - 2 * math.sin(alpha / 2)

        low = delta / self.r
        high = delta / self.r + 1.0

        for _ in range(200):  # Sufficient iterations for precision
            mid = (low + high) / 2
            if f(mid) < delta:
                low = mid
            else:
                high = mid

        return (self.r * high) / self.v  # time = distance / velocity

    def process(self, n, r, v, lines):
        results = []
        for line in lines:
            parts = list(map(int, line.split()))
            s, f = parts[0], parts[1]
            delta = f - s
            time = self.solve_alpha(delta)
            results.append(time)
        return results

