    n = int(lines[0])
    pts = []
    for i in range(1, n + 1):
        pt = tuple(map(int, lines[i].split()))
        pts.append(pt)

    def orient(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def on_segment(p1, p2, q):
        return min(p1[0], p2[0]) <= q[0] <= max(p1[0], p2[0]) and \
               min(p1[1], p2[1]) <= q[1] <= max(p1[1], p2[1])

    def segments_intersect(p1, p2, p3, p4):
        o1 = orient(p1, p2, p3)
        o2 = orient(p1, p2, p4)
        o3 = orient(p3, p4, p1)
        o4 = orient(p3, p4, p2)

        if ((o1 > 0 and o2 < 0) or (o1 < 0 and o2 > 0)) and \
           ((o3 > 0 and o4 < 0) or (o3 < 0 and o4 > 0)):
            return True

        if o1 == 0 and on_segment(p1, p2, p3):
            return True
        if o2 == 0 and on_segment(p1, p2, p4):
            return True
        if o3 == 0 and on_segment(p3, p4, p1):
            return True
        if o4 == 0 and on_segment(p3, p4, p2):
            return True

        return False

    def triangles_intersect(t1, t2):
        p = [pts[i] for i in t1]
        q = [pts[i] for i in t2]
        edges1 = [(p[0], p[1]), (p[1], p[2]), (p[2], p[0])]
        edges2 = [(q[0], q[1]), (q[1], q[2]), (q[2], q[0])]

        for e1 in edges1:
            for e2 in edges2:
                if segments_intersect(e1[0], e1[1], e2[0], e2[1]):
                    return True
        return False

    triangles = [(i, j, k) for i in range(n) for j in range(i+1, n) for k in range(j+1, n)]

    cnt = 0
    for i in range(len(triangles)):
        t1 = triangles[i]
        for j in range(i+1, len(triangles)):
            t2 = triangles[j]
            if not triangles_intersect(t1, t2):
                cnt += 1

    return f"{cnt}\n"

