def get_square_free_part(n):
    result = 1
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            cnt = 0
            while temp % d == 0:
                cnt += 1
                temp //= d
            if cnt % 2 == 1:
                result *= d
        d += 1
    if temp > 1:
        result *= temp
    return result

