    var_to_clauses = [[] for _ in range(m)]
    for ci, clause_vars in enumerate(clauses):
        for v in clause_vars:
            var_to_clauses[v].append(ci)

    # Count satisfying assignments
    # Variables appearing 0 times: free, contribute 2
    # Variables appearing 1 time: contribute 2 (always satisfied by setting true)
    # Variables appearing 2 times: need component analysis

    single_once = m  # Count of all variables

    for v in range(m):
        len_clauses = len(var_to_clauses[v])
        if len_clauses == 0:
            single_once -= 1

    # Build components based on which clauses variables appear in
    def bfs_component(start_v):
        """Find all variables in same component as start_v"""
        component_vars = set([start_v])
        var_comp = {start_v}
        visited = [False] * m
        visited[start_v] = True

        stack = deque([start_v])

        while stack:
            v = stack.popleft()

            for ci in var_to_clauses[v]:
                for other in clauses[ci]:
                    if other not in visited and other in var_comp or other not in var_comp:
                        if other not in visited:
                            visited[other] = True
                            stack.append(other)
                            var_comp.add(other)
                            if other not in component_vars:
                                component_vars.add(other)
                            else:
                                component_vars.add(other)
                            if other not in var_comp:
                                var_comp.add(other)

        return component_vars

    # Track all components
    all_visited = [False] * m
    component_sizes = []

    # Process components
    for v in range(m):
        if all_visited[v]:
            continue

        if len(var_to_clauses[v]) == 0 or len(var_to_clauses[v]) == 1:
            all_visited[v] = True
            continue

        # BFS to find whole component
        component = [v]
        seen = {v}
        stack = [v]
        all_visited[v] = True

        while stack:
            curr = stack.pop()
            if curr < n:  # Actually a variable
                for ci in var_to_clauses[curr]:
                    # Find other vars in this clause
                    for var_in in clauses[ci]:
                        if var_in not in seen and var_in < m:
                            seen.add(var_in)
                            all_visited[var_in] = True
                            stack.append(var_in)
                            if var_in not in component:
                                component.append(var_in)

        component_sizes.append(len(component))

    # Count free variables (appear 0 times)
    free_count = m - sum(1 for v in range(m) if 0 < len(var_to_clauses[v]) <= 2)

    actual_free = 0
    for v in range(m):
        if len(var_to_clauses[v]) == 0:
            actual_free += 1

    # Calculate: 2^free * 2^once * component_contribution
    ans = pow(2, actual_free, MOD)

    # For components of twice-appearing variables, use component formula
    twice_count = 0
    once_count = 0

    for v in range(m):
        lc = len(var_to_clauses[v])
        if lc == 0:
            continue
        elif lc == 1:
            once_count += 1
        else:
            twice_count += 1

    ans = (ans * pow(2, once_count, MOD)) % MOD

    # Twice appearing: simple case where each contributes 2
    ans = (ans * pow(2, twice_count, MOD)) % MOD

    return str(ans) + '\n'

