def solution(input_str):
    lines = input_str.strip().split('\n')
    s = lines[0]
    t = lines[1]

    result = []

    while True:
        if s == 'a' * len(s) and t == 'b' * len(t):
            break
        if s == 'b' * len(s) and t == 'a' * len(t):
            break

        # If strings are the same, count positions where characters differ
        if s == t:
            break

        # Find uniform prefix positions for both strings
        pos_a_s, pos_b_s = -1, -1
        for i in range(len(s) + 1):
            if s[:i].count('b') == 0:
                pos_a_s = i
            if s[:i].count('a') == 0:
                pos_b_s = i

        pos_a_t, pos_b_t = -1, -1
        for i in range(len(t) + 1):
            if t[:i].count('b') == 0:
                pos_a_t = i
            if t[:i].count('a') == 0:
                pos_b_t = i

        # Try all combinations of uniform positions
        found = False
        for i in [pos_a_s, pos_b_s]:
            for j in [pos_a_t, pos_b_t]:
                if i == -1 or j == -1:
                    continue

                # Execute the swap
                new_s = t[:j] + s[i:]
                new_t = s[:i] + t[j:]

                # Check if this makes progress
                if (new_s == 'a' * len(new_s) or new_t == 'b' * len(new_t) or
                    new_s == 'b' * len(new_s) or new_t == 'a' * len(new_t)):
                    s = new_s
                    t = new_t
                    result.append((i, j))
                    found = True
                    break

        if not found:
            break

    output_lines = [str(len(result))]
    for i, j in result:
        output_lines.append(f"{i} {j}")
    return '\n'.join(output_lines)
